import { subprocessEnvironment } from '../utils/subprocessEnvironment';
import { execFile } from 'child_process';
import fs from 'fs/promises';
import os from 'os';
import path from 'path';
import { promisify } from 'util';
import { LibraryError } from './libraryErrors';
import { getWindowTopLeft } from '../utils/windowPlacement';

interface FolderPickerCommand {
  executable: string;
  args: string[];
  cancelExitCode?: number;
}
interface FolderPickerOptions {
  commands?: FolderPickerCommand[];
}

const execute = promisify(execFile);
const PICKER_TIMEOUT_MS = 5 * 60 * 1000;
const PICKER_OUTPUT_LIMIT = 64 * 1024;
const PICKER_TITLE = 'Open a Rivet project';
const MAC_FOLDER_SCRIPT = `
ObjC.import('AppKit');
const anchor = $.NSEvent.mouseLocation;
const application = $.NSApplication.sharedApplication;
application.setActivationPolicy($.NSApplicationActivationPolicyAccessory);
application.finishLaunching;
const panel = $.NSOpenPanel.openPanel;
panel.canChooseFiles = false;
panel.canChooseDirectories = true;
panel.allowsMultipleSelection = false;
panel.title = 'Open a Rivet project';
panel.prompt = 'Open';
const screens = $.NSScreen.screens;
let screen = $.NSScreen.mainScreen;
for (let index = 0; index < screens.count; index++) {
  const candidate = screens.objectAtIndex(index);
  if ($.NSPointInRect(anchor, candidate.frame)) {
    screen = candidate;
    break;
  }
}
const visible = screen.visibleFrame;
const position = (${getWindowTopLeft.toString()})({
  anchor,
  bounds: {
    x: visible.origin.x,
    y: visible.origin.y,
    width: visible.size.width,
    height: visible.size.height,
  },
  size: {
    width: panel.frame.size.width,
    height: panel.frame.size.height,
  },
});
panel.setFrameTopLeftPoint($.NSMakePoint(position.x, position.y));
application.activateIgnoringOtherApps(true);
panel.makeKeyAndOrderFront(null);
panel.runModal === $.NSModalResponseOK ? ObjC.unwrap(panel.URL.path) : '';
`;
const WINDOWS_FOLDER_SCRIPT = `
$ErrorActionPreference = 'Stop'
[Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
Add-Type -AssemblyName System.Windows.Forms
[System.Windows.Forms.Application]::EnableVisualStyles()
$dialog = [System.Windows.Forms.FolderBrowserDialog]::new()
$dialog.Description = 'Open a Rivet project'
try {
  if ($dialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
    [Console]::Write($dialog.SelectedPath)
  }
} finally {
  $dialog.Dispose()
}`;

const folderPickerCommands = (): FolderPickerCommand[] => {
  switch (process.platform) {
    case 'darwin':
      return [
        {
          executable: '/usr/bin/osascript',
          args: ['-l', 'JavaScript', '-e', MAC_FOLDER_SCRIPT],
        },
      ];
    case 'win32':
      return [
        {
          executable: 'powershell.exe',
          args: [
            '-NoProfile',
            '-NonInteractive',
            '-STA',
            '-Command',
            WINDOWS_FOLDER_SCRIPT,
          ],
        },
      ];
    case 'linux': {
      const zenity = {
        executable: 'zenity',
        args: ['--file-selection', '--directory', '--title', PICKER_TITLE],
        cancelExitCode: 1,
      };
      const kdialog = {
        executable: 'kdialog',
        args: ['--getexistingdirectory', os.homedir(), '--title', PICKER_TITLE],
        cancelExitCode: 1,
      };
      return process.env.XDG_CURRENT_DESKTOP?.toLowerCase().includes('kde')
        ? [kdialog, zenity]
        : [zenity, kdialog];
    }
    default:
      return [];
  }
};

export class ProjectFolderPicker {
  private active: AbortController | null = null;
  private readonly commands: FolderPickerCommand[];

  constructor({ commands = folderPickerCommands() }: FolderPickerOptions = {}) {
    this.commands = commands;
  }

  async pick(): Promise<string | null> {
    if (this.active)
      throw new LibraryError(
        'folder_picker_busy',
        'A folder picker is already open. Choose a folder or cancel it first.',
      );
    const controller = new AbortController();
    this.active = controller;
    try {
      for (const command of this.commands) {
        let output: string;
        try {
          const result = await execute(command.executable, command.args, {
            env: subprocessEnvironment('desktop'),
            encoding: 'utf8',
            windowsHide: true,
            timeout: PICKER_TIMEOUT_MS,
            maxBuffer: PICKER_OUTPUT_LIMIT,
            signal: controller.signal,
          });
          output = result.stdout;
        } catch (error) {
          if (controller.signal.aborted) return null;
          const failure = error as { code?: string | number; stderr?: string };
          if (failure.code === 'ENOENT') continue;
          if (
            command.cancelExitCode !== undefined &&
            failure.code === command.cancelExitCode &&
            !failure.stderr?.trim()
          )
            return null;
          throw new LibraryError(
            'folder_picker_unavailable',
            'Could not open the system folder picker. Try again, or run rivet open --project <path> in a terminal.',
          );
        }
        const selected = output.replace(/\r?\n$/, '');
        if (!selected) return null;
        if (!path.isAbsolute(selected))
          throw new Error('Select an existing folder.');
        const canonical = await fs.realpath(selected);
        if (!(await fs.stat(canonical)).isDirectory())
          throw new Error('Select an existing folder.');
        return canonical;
      }
      throw new LibraryError(
        'folder_picker_unavailable',
        'No system folder picker is available. On Linux, install Zenity or KDialog, or run rivet open --project <path> in a terminal.',
      );
    } finally {
      this.active = null;
    }
  }

  close(): void {
    this.active?.abort();
  }
}
